/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_calendar_events_sync_hash` BEFORE UPDATE ON `calendar_events` FOR EACH ROW BEGIN
  IF NEW.is_external = TRUE AND (
    OLD.title != NEW.title OR
    OLD.starts_at_utc != NEW.starts_at_utc OR
    OLD.ends_at_utc != NEW.ends_at_utc OR
    COALESCE(OLD.location, '') != COALESCE(NEW.location, '')
  ) THEN
    SET NEW.sync_hash = SHA2(CONCAT(
      COALESCE(NEW.title, ''),
      '|',
      NEW.starts_at_utc,
      '|',
      NEW.ends_at_utc,
      '|',
      COALESCE(NEW.location, '')
    ), 256);
  END IF;
END */;;
