/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `events_set_approved_at` BEFORE INSERT ON `events` FOR EACH ROW BEGIN
  
  IF NEW.creator_approved = 1 THEN
    SET NEW.creator_approved_at = UTC_TIMESTAMP(3);
  END IF;
END */;;
