DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_find_mutual_availability`(
  IN p_user1_id INT UNSIGNED,
  IN p_user2_id INT UNSIGNED,
  IN p_start_date DATETIME,
  IN p_end_date DATETIME,
  IN p_min_duration_minutes INT
)
BEGIN
  WITH busy_slots AS (
    SELECT 
      starts_at_utc as slot_start,
      ends_at_utc as slot_end
    FROM `nexus`.`v_user_busy_slots`
    WHERE user_id IN (p_user1_id, p_user2_id)
      AND starts_at_utc < p_end_date
      AND ends_at_utc > p_start_date
    ORDER BY slot_start
  ),
  merged_slots AS (
    SELECT 
      MIN(slot_start) as gap_end,
      slot_end as next_start
    FROM busy_slots
    GROUP BY slot_end
  )
  SELECT 
    GREATEST(p_start_date, gap_end) as free_start,
    LEAST(p_end_date, next_start) as free_end,
    TIMESTAMPDIFF(MINUTE, GREATEST(p_start_date, gap_end), LEAST(p_end_date, next_start)) as duration_minutes
  FROM merged_slots
  WHERE TIMESTAMPDIFF(MINUTE, GREATEST(p_start_date, gap_end), LEAST(p_end_date, next_start)) >= p_min_duration_minutes
  ORDER BY free_start;
END ;;
